{
  "name": "loss_hinge_regret_weighted",
  "intuition": "Shift from probabilistic/logistic pairwise likelihood to a max-margin ranking objective where the margin is set by an external regret signal: if the winner is much better (high regret), enforce a larger separation; if not, allow a smaller margin. This turns preference learning into cost-calibrated large-margin ranking.",
  "pseudocode": "margin = clamp(m0 + beta*delta_regret, m_min, m_max); x = alpha*scale*(lpw-lpl); loss = relu(margin - x); return weighted_mean(loss)",
  "hyperparams": {
    "paradigm_family": "max_margin",
    "signal_family": "delta_regret",
    "link_family": "hinge",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "relu",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_regret"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_regret = batch['delta_regret']\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.0))\n    m0 = float(hp.get('m0', 1.0))\n    beta = float(hp.get('beta', 1.0))\n    m_min = float(hp.get('m_min', 0.0))\n    m_max = float(hp.get('m_max', 10.0))\n\n    x = alpha * scale * (lpw - lpl)\n    margin = m0 + beta * delta_regret.detach()\n    margin = ops.clamp(margin, m_min, m_max)\n\n    loss = ops.relu(margin - x)\n\n    if weight is not None:\n        loss = loss * weight\n        denom = ops.clamp(weight.sum(), 1e-12, 1e12)\n        return loss.sum() / denom\n    return loss.mean()\"\n}

{
  "name": "loss_pairwise_hinge_regret",
  "intuition": "Switch from probabilistic (logsigmoid) to max-margin ranking: enforce a minimum separation between winner and loser log-probabilities, with the required margin scaled by observed regret (how much worse the loser is than the winner). This focuses gradients on violated constraints and ignores already-satisfied pairs.",
  "pseudocode": "gap = (lpw - lpl)\nmargin = base_margin + regret_scale * relu(delta_regret)\nloss_i = relu(margin - gap)\nloss = weighted_mean(loss_i)",
  "hyperparams": {
    "paradigm_family": "max_margin_ranking",
    "signal_family": "delta_regret",
    "link_family": "hinge",
    "agg_family": "weighted_mean",
    "constraint_family": "softplus_stabilized"
  },
  "operators_used": [
    "relu",
    "softplus"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_regret"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_regret = batch['delta_regret']\n\n    hp = extra.get('hyperparams', {})\n    base_margin = float(hp.get('base_margin', 1.0))\n    regret_scale = float(hp.get('regret_scale', 1.0))\n\n    # Stabilize extreme values without hard clipping: softplus(x)-softplus(-x) ~ x, bounded gradients.\n    gap = ops.softplus(lpw - lpl) - ops.softplus(-(lpw - lpl))\n\n    margin = base_margin + regret_scale * ops.relu(delta_regret.detach())\n    loss = ops.relu(margin - gap)\n\n    if weight is not None:\n        loss = loss * weight\n        denom = ops.relu(weight).sum() + 1e-8\n        return loss.sum() / denom\n\n    return loss.mean()\"\n}

{
  "name": "zscore_margin_logsig",
  "intuition": "Use the outcome improvement (delta_z) as a self-normalized margin: if the winner has better objective than the loser, push log_prob_w above log_prob_l by a margin proportional to a z-scored delta_z. Z-scoring stabilizes scale across instances/batches, while clamping and a softplus margin keep gradients bounded and emphasize large, reliable improvements.",
  "pseudocode": "Let d = delta_z. m = softplus(alpha * zscore(d)). Loss = -E[ weight * logsigmoid( (log_prob_w - log_prob_l) - clamp(m, 0, m_max) ) ].",
  "hyperparams": {
    "paradigm_family": "pairwise_preference_margin",
    "signal_family": "delta_z",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "nonneg_weight_clamped_margin",
    "other_hparams": "alpha (margin scale), m_max (margin clamp)"
  },
  "operators_used": ["logsigmoid", "softplus", "clamp", "zscore"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_z"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = model_output[\"log_prob_w\"]\n    log_prob_l = model_output[\"log_prob_l\"]\n    weight = model_output[\"weight\"]\n    delta_z = model_output[\"delta_z\"]\n\n    alpha = float(extra.get(\"alpha\", extra.get(\"hyperparams\", {}).get(\"alpha\", 1.0)))\n    m_max = float(extra.get(\"m_max\", extra.get(\"hyperparams\", {}).get(\"m_max\", 10.0)))\n\n    d_norm = ops.zscore(delta_z)\n    margin = ops.softplus(d_norm * alpha)\n    margin = ops.clamp(margin, 0.0, m_max)\n\n    diff = (log_prob_w - log_prob_l) - margin\n    per_pair = -ops.logsigmoid(diff)\n\n    loss = (per_pair * weight).sum() / (weight.sum() + 1e-8)\n    return loss\n"
}
